-- 30 dúvidas, objeções e situações prováveis (26/10). Respostas no tom da recepção, só com fatos
-- já confirmados pelo salão (docs/10). Onde o salão ainda não informou, a orientação é confirmar
-- com a equipe (transferir_para_humano, motivo incerteza) — nunca inventar.
-- fonte = 'ampliize' → revisar com a Karol/Tauã; aprovado = true para o agente já usar.
insert into public.kb_itens (categoria, pergunta, resposta, palavras_chave, fonte, aprovado, ativo) values
-- objeções
('geral', 'Achei caro / tá caro / muito caro', 'ORIENTAÇÃO: acolha sem se justificar demais. Ex.: "entendo, flor". Diga que o valor é o da tabela do salão e que, quando depende de comprimento ou volume, é confirmado na avaliação. Pergunte o que ela tem em mente e, se fizer sentido, ofereça um serviço mais simples do catálogo (consultar_servicos). Não ofereça desconto.', array['caro','cara','salgado','puxado','valor alto','barato','mais em conta'], 'ampliize', true, true),
('geral', 'Tem desconto? Faz um precinho? Tem promoção?', 'ORIENTAÇÃO: não prometa desconto. Diga que vai ver com a equipe se tem alguma condição no momento e use transferir_para_humano (incerteza).', array['desconto','promocao','promoção','precinho','abatimento','cupom'], 'ampliize', true, true),
('geral', 'Vou pensar / depois eu vejo / te aviso', 'ORIENTAÇÃO: sem pressão. Ex.: "tranquilo! se quiser já deixo seu horário reservado e, se mudar de ideia, é só avisar que a gente desmarca, sem custo nenhum". O salão não cobra sinal e permite cancelar/remarcar quando precisar.', array['pensar','depois','vejo','aviso','ver','talvez','mais tarde'], 'ampliize', true, true),
('geral', 'Não tem horário antes? Tá muito longe a data', 'ORIENTAÇÃO: use consultar_horarios em outros dias próximos e com outras profissionais que fazem o serviço. Ofereça 2 ou 3 opções mais cedo.', array['antes','cedo','longe','demora','urgente','hoje','amanha','encaixe','encaixar'], 'ampliize', true, true),
('geral', 'Não tenho tempo / trabalho o dia todo', 'ORIENTAÇÃO: o salão abre de terça a sábado, das 9h às 18h. Sugira o sábado ou o primeiro/último horário do dia (consultar_horarios).', array['tempo','trabalho','corrido','correria','horario','sabado','cedo','tarde'], 'ampliize', true, true),
('geral', 'Já faço em outro salão / tenho minha cabeleireira', 'ORIENTAÇÃO: respeite, sem falar mal de ninguém. Convide com leveza: "se quiser conhecer, vai ser um prazer te receber". Para alongamento, luzes, selagem ou coloração, lembre que a avaliação/teste de mecha é gratuita.', array['outro salao','outra','cabeleireira','ja faco','ja tenho'], 'ampliize', true, true),
('geral', 'Tenho medo de estragar meu cabelo / medo de química', 'ORIENTAÇÃO: acolha. Explique que para química, coloração, luzes, selagem e alongamento o salão faz antes um teste de mecha ou avaliação gratuitos, justamente para ver se é seguro. Ofereça agendar o teste/avaliação.', array['medo','estragar','quebrar','cair','danificar','quimica','química','seguro'], 'ampliize', true, true),
('geral', 'Quero falar com uma pessoa / com a Karol / com a dona', 'ORIENTAÇÃO: diga que vai chamar alguém da equipe e use transferir_para_humano (pedido_cliente).', array['pessoa','humano','atendente','karol','dona','gerente','responsavel'], 'ampliize', true, true),
('geral', 'Isso é robô? Estou falando com uma IA?', 'ORIENTAÇÃO: seja honesta e leve: é a assistente de IA do salão e a equipe acompanha tudo; se ela preferir falar com alguém da equipe, é só dizer. Continue ajudando.', array['robo','robô','bot','ia','inteligencia artificial','automatico','pessoa de verdade'], 'ampliize', true, true),
('geral', 'Fui mal atendida / não gostei do resultado / reclamação', 'ORIENTAÇÃO: acolha em uma frase, sem discutir nem prometer nada, e transfira imediatamente (reclamacao).', array['reclamacao','reclamar','nao gostei','ruim','estragou','insatisfeita','mal atendida','problema'], 'ampliize', true, true),
-- pagamento e políticas
('pagamento', 'Aceita cartão? Aceita PIX? Posso pagar em dinheiro?', 'Aceitamos PIX, dinheiro e cartão.', array['cartao','cartão','pix','dinheiro','debito','credito','pagamento'], 'ampliize', true, true),
('pagamento', 'Dá para parcelar?', 'ORIENTAÇÃO: o salão aceita cartão, mas as condições de parcelamento ainda não foram informadas. Diga que vai confirmar com a equipe e use transferir_para_humano (incerteza).', array['parcelar','parcela','vezes','parcelado','credito'], 'ampliize', true, true),
('pagamento', 'Tenho que pagar antes? Pago na hora?', 'Não precisa pagar nada antes, nem sinal: o pagamento é no salão, no dia (PIX, dinheiro ou cartão).', array['antes','adiantado','sinal','na hora','pagar quando','reserva'], 'ampliize', true, true),
('politica', 'Faltei / perdi o horário, posso remarcar?', 'Pode sim, sem problema. ORIENTAÇÃO: pergunte o melhor dia e horário e siga a regra de agendamento (agendar com remarcar=true se ela ainda tiver horário futuro).', array['faltei','perdi','esqueci','nao fui','remarcar'], 'ampliize', true, true),
('politica', 'Quero cancelar meu horário', 'Pode cancelar quando precisar, não exigimos antecedência. ORIENTAÇÃO: confirme com ela qual horário (dia) e use cancelar_agendamento; depois pergunte se quer remarcar.', array['cancelar','desmarcar','nao vou poder','nao vou conseguir','cancelamento'], 'ampliize', true, true),
('politica', 'Quero mudar o horário / trocar o dia', 'ORIENTAÇÃO: pergunte o novo dia e horário (e se mantém a profissional) e use agendar com remarcar=true; o horário antigo é cancelado sozinho.', array['mudar','trocar','outro horario','outro dia','remarcar','adiantar','passar para'], 'ampliize', true, true),
('politica', 'Vou me atrasar / estou a caminho', 'A tolerância é de 15 minutos; se passar de 20 minutos e não conseguirmos falar com você, o horário é cancelado. ORIENTAÇÃO: tranquilize e, se for resposta a lembrete, registrar_retorno_lembrete (atraso).', array['atrasar','atraso','caminho','chegando','transito','trânsito','demorar'], 'ampliize', true, true),
('politica', 'Abre em feriado?', 'ORIENTAÇÃO: o horário normal é de terça a sábado, das 9h às 18h; funcionamento em feriado ainda não foi informado. Confirme com a equipe (transferir_para_humano, incerteza).', array['feriado','natal','ano novo','carnaval','ponto facultativo'], 'ampliize', true, true),
-- serviços e atendimento
('servico', 'Quanto tempo demora o serviço?', 'ORIENTAÇÃO: use consultar_servicos (campo duracao_min) e responda em linguagem natural ("leva uns 50 minutos").', array['demora','tempo','duracao','duração','quanto tempo','horas'], 'ampliize', true, true),
('servico', 'Quem é a melhor profissional para isso? Quem faz?', 'ORIENTAÇÃO: use consultar_servicos (quem_faz, já em ordem de quem mais faz) e cite 2 ou 3 nomes, sem dizer que uma é melhor que a outra.', array['melhor','quem faz','indica','recomenda','especialista','profissional'], 'ampliize', true, true),
('servico', 'Tem horário hoje? Tem encaixe?', 'ORIENTAÇÃO: o salão abre de terça a sábado, das 9h às 18h. Use consultar_horarios para hoje e ofereça 2 ou 3 opções; se não houver, ofereça o próximo dia.', array['hoje','agora','encaixe','encaixar','urgente','ainda hoje'], 'ampliize', true, true),
('servico', 'Fazem penteado / maquiagem / produção para festa?', 'ORIENTAÇÃO: o catálogo tem Penteado e Maquiagem + cílios. Use consultar_servicos para preço e quem faz e ofereça agendar.', array['penteado','maquiagem','make','produção','producao','festa','casamento','formatura','noiva'], 'ampliize', true, true),
('servico', 'Quais hidratações vocês têm?', 'ORIENTAÇÃO: há várias hidratações no catálogo (L''Oréal, Mirra, Truss, Joico, entre outras). Use consultar_servicos com "hidratação" e cite no máximo 2 ou 3, com preço.', array['hidratacao','hidratação','tratamento','reconstrucao','nutricao','cabelo seco'], 'ampliize', true, true),
('servico', 'Atendem homem? Fazem corte masculino?', 'ORIENTAÇÃO: use consultar_servicos com "masculino"/"corte"; se não houver serviço masculino no catálogo, diga que vai confirmar com a equipe (transferir_para_humano, incerteza).', array['homem','masculino','marido','barba','corte masculino','namorado'], 'ampliize', true, true),
('servico', 'Atendem criança?', 'ORIENTAÇÃO: o salão ainda não informou isso. Diga que vai confirmar com a equipe (transferir_para_humano, incerteza).', array['crianca','criança','filha','filho','infantil','menina','idade'], 'ampliize', true, true),
('servico', 'Quero marcar para mim e outra pessoa juntas (mãe e filha, amiga)', 'ORIENTAÇÃO: agende uma de cada vez com agendar (no mesmo horário com profissionais diferentes, ou em sequência). A segunda pessoa precisa de nome completo para o cadastro. Se ficar complicado, transfira (pedido_cliente).', array['duas','juntas','amiga','mae','mãe','filha','irma','nós duas','para nos'], 'ampliize', true, true),
('servico', 'Grávida pode fazer química / progressiva / coloração?', 'ORIENTAÇÃO: não dê orientação de saúde. Diga com carinho que a equipe vai orientar direitinho e transfira (incerteza).', array['gravida','grávida','gestante','gravidez','amamentando','amamentar'], 'ampliize', true, true),
('servico', 'Tenho alergia / couro cabeludo sensível', 'ORIENTAÇÃO: não dê orientação de saúde. Acolha e transfira (incerteza) para a equipe avaliar; para química, o teste de mecha gratuito existe justamente para isso.', array['alergia','alergica','alérgica','sensivel','sensível','coceira','irritacao','dermatite'], 'ampliize', true, true),
('servico', 'Preciso ir com o cabelo lavado? Como devo ir?', 'ORIENTAÇÃO: o salão ainda não informou cuidados de preparo. Diga que vai confirmar com a equipe (transferir_para_humano, incerteza).', array['lavado','lavar','sujo','preparo','como ir','antes do procedimento','cuidados'], 'ampliize', true, true),
('servico', 'Quanto tempo dura a selagem / progressiva? De quanto em quanto tempo faz manutenção?', 'ORIENTAÇÃO: durabilidade e intervalo de manutenção dependem do cabelo; isso é orientado na avaliação ou teste de mecha (gratuitos). Ofereça agendar o teste; se ela insistir, transfira (incerteza).', array['dura','durabilidade','quanto tempo dura','manutencao','manutenção','retoque','de quanto em quanto'], 'ampliize', true, true);
